+.brand a{text-decoration:none}
+.nav-links{display:flex;gap:22px;align-items:center}
+.nav-links a{font-size:14px;letter-spacing:.02em;text-transform:none;opacity:.92}
+.nav-links a[aria-current="page"]{opacity:1;text-decoration:underline;text-underline-offset:6px}
+
+.hamburger{display:none;appearance:none;border:1px solid var(--hairline);background:transparent;color:inherit;border-radius:999px;padding:10px 12px;line-height:0;cursor:pointer}
+.hamburger svg{width:18px;height:18px}
+
+.mobile-overlay{
+  position:fixed;inset:0;z-index:80;
+  background:var(--bg);
+  display:none;
+}
+.mobile-overlay[data-open="true"]{display:block}
+.overlay-inner{height:100%;display:flex;flex-direction:column;justify-content:space-between;padding:22px 28px}
+.overlay-top{display:flex;align-items:center;justify-content:space-between}
+.overlay-links{display:flex;flex-direction:column;gap:14px;padding:50px 0 0}
+.overlay-links a{font-family:var(--serif);font-size:38px;letter-spacing:-.03em;line-height:1.05}
+.overlay-foot{border-top:1px solid var(--hairline);padding-top:16px;color:var(--muted);font-size:13px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
+
+main{padding:72px 0 96px}
+
+.kicker{font-size:12px;text-transform:uppercase;letter-spacing:.14em;color:var(--muted)}
+.hairline{height:1px;background:var(--hairline);margin:38px 0}
+
+.hero{
+  display:grid;
+  grid-template-columns: 1.3fr .7fr;
+  gap:40px;
+  align-items:end;
+}
+.hero h1{
+  font-family:var(--serif);
+  font-weight:700;
+  font-size:clamp(44px, 6vw, 86px);
+  line-height:0.98;
+  letter-spacing:-.04em;
+  margin:0;
+}
+.hero p{margin:0;color:var(--muted);max-width:38ch}
+
+.media-showcase{
+  margin-top:54px;
+  display:grid;
+  grid-template-columns:1.1fr .9fr 1fr;
+  gap:18px;
+  align-items:stretch;
+}
