+.media-block[data-tone="sand"]{background:linear-gradient(135deg, #D1B68C, #E6D7BE)}
+.media-caption{display:flex;justify-content:space-between;gap:16px;margin-top:10px;color:var(--muted);font-size:13px}
+
+.marquee-wrap{margin-top:64px;padding:28px 0;border-top:1px solid var(--hairline);border-bottom:1px solid var(--hairline)}
