+.marquee-sep{opacity:.35}
+
+.about{
+  margin-top:76px;
+  display:grid;
+  grid-template-columns: 260px 1fr;
+  gap:40px;
+}
+.about h2{margin:0;font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
+.about .copy{max-width:76ch}
+.about .copy p{margin:0 0 18px;color:var(--muted)}
+
+.page-title{
+  font-family:var(--serif);
+  font-weight:700;
+  letter-spacing:-.04em;
+  margin:0;
+}
+
+.letter{
+  max-width:var(--read);
+  margin:0 auto;
+}
+.letter h1{font-size:clamp(44px, 5.4vw, 76px);line-height:1.0}
+.letter .lead{font-size:18px;color:var(--muted);max-width:58ch}
+.letter .meta{display:flex;gap:16px;flex-wrap:wrap;margin-top:14px;color:var(--muted);font-size:13px}
+.letter .body{margin-top:34px;font-size:18px;line-height:1.7}
+.letter .body p{margin:0 0 22px}
+.letter .sig{margin-top:36px;color:var(--muted)}
+.dropcap:first-letter{float:left;font-family:var(--serif);font-size:64px;line-height:.9;margin:8px 10px 0 0;font-weight:700}
+
+.services{
+  display:grid;
+  grid-template-columns: 1fr 1fr;
+  gap:44px;
+  align-items:start;
+}
+.services .philosophy h1{font-size:clamp(44px, 5.8vw, 84px);line-height:1}
+.services .philosophy p{color:var(--muted);max-width:52ch;font-size:16px}
+.services .pill{display:inline-flex;align-items:center;gap:10px;border:1px solid var(--hairline);border-radius:999px;padding:10px 14px;color:var(--muted);font-size:13px}
+.services .details h2{font-family:var(--serif);font-size:22px;margin:0 0 12px}
+.services .details h3{font-family:var(--serif);font-size:26px;margin:26px 0 8px;letter-spacing:-.02em}
+.services .details p{margin:0 0 14px;color:var(--muted)}
+
+.clients-hero{display:grid;grid-template-columns:1fr .8fr;gap:44px;align-items:end}
+.clients-hero h1{font-size:clamp(56px, 7vw, 110px);line-height:.92}
+.clients-hero p{margin:0;color:var(--muted);max-width:46ch}
+
+.clients-grid{margin-top:44px;display:grid;grid-template-columns:repeat(3, minmax(0,1fr));gap:26px 28px}
+.client-card{padding:20px 18px;border:1px solid var(--hairline);border-radius:16px;background:color-mix(in srgb, var(--bg) 88%, #fff 12%)}
+.client-card h3{margin:0 0 10px;font-family:var(--serif);font-size:22px;letter-spacing:-.02em}
+.client-card p{margin:0;color:var(--muted);font-size:14px;line-height:1.55}
+
+.contact{
+  min-height:calc(100vh - 140px);
+  display:flex;
+  flex-direction:column;
+  justify-content:center;
+}
+.contact h1{font-size:clamp(84px, 12vw, 170px);line-height:.86}
+.contact-links{margin-top:24px;display:flex;gap:24px;flex-wrap:wrap}
+.contact-links a{font-size:16px;color:var(--muted)}
+
+.site-footer{border-top:1px solid var(--hairline);padding:24px 0 44px;color:var(--muted);font-size:13px}
+.site-footer .inner{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap}
+
+@media (prefers-reduced-motion: reduce){
+  .marquee-track{transform:none !important}
+}
+
+@media (max-width: 920px){
+  main{padding:52px 0 76px}
+  .hero{grid-template-columns:1fr;gap:18px}
+  .hero p{max-width:60ch}
+  .media-showcase{grid-template-columns:1fr;gap:14px}
+  .media-block{min-height:220px}
+  .about{grid-template-columns:1fr;gap:18px}
+  .services{grid-template-columns:1fr;gap:26px}
+  .clients-hero{grid-template-columns:1fr;gap:18px}
+  .clients-grid{grid-template-columns:repeat(2, minmax(0,1fr))}
+}
+
+@media (max-width: 640px){
+  .container{padding:0 18px}
+  .nav-links{display:none}
+  .hamburger{display:inline-flex;align-items:center;justify-content:center}
+  .overlay-inner{padding:18px}
+  .overlay-links a{font-size:34px}
+  .clients-grid{grid-template-columns:1fr}
+  .contact-links{gap:16px}
+}
+
